"""Listening exercises (CAE Parts 1-4). Run tools/build_content.py to validate & export JSON."""

def L(sp, v, t):
    return {"speaker": sp, "voice": v, "text": t}

def D(i, reason, quote=None):
    d = {"optionIndex": i, "reason": reason}
    if quote:
        d["trapQuote"] = quote
    return d

